import time
import sys
import signal
import gpiozero

# Initialize GPIO pins
pins = [12, 13, 18, 19, 22, 23]
pwm_pins = [gpiozero.PWMOutputDevice(pin) for pin in pins]

def check_validity(value):
    # Add your own validity check here
    return 0 <= value <= 1

def exit_gracefully(signum, frame):
    print("Exiting...")
    for pin in pwm_pins:
        pin.close()
    sys.exit(0)

# Register the exit function to be called on interrupt
signal.signal(signal.SIGINT, exit_gracefully)

try:
    while True:
        for i, pin in enumerate(pwm_pins):
            # Generate a random value for the PWM output
            value = float(i) / len(pwm_pins)
            if check_validity(value):
                pin.value = value
                print(f"Pin {pins[i]} set to {value}")
            else:
                print(f"Invalid value {value} for pin {pins[i]}")
        time.sleep(2)
except KeyboardInterrupt:
    exit_gracefully(0, None)
